  _launchVisualPath(sprite, travel) {
    this.scene.tweens.add({
      targets: sprite, x: travel.end.x, y: travel.end.y,
      duration: travel.durationMs, ease: "Linear",
      onComplete: () => this._releaseProjectile(sprite),
    });
  }

  _getTravelMs(distance) {
    return distance * this.tileSize / C.speedPxPerSecond * 1000;
  }

  _spawnImpact(hit, travel, paletteIndex) {
    const contact = resolveStellarLanceHit(travel, hit, this.tileSize);
    this.vfx.spawnImpact({ ...hit, worldPoint: contact.worldPoint },
      paletteIndex, contact.delayMs, travel.angle);
  }

  _releaseProjectile(projectile) {
    this.projectiles.delete(projectile);
    this.scene.tweens?.killTweensOf?.(projectile);
    projectile?.destroy?.();
  }

  getBuffSnapshot(nowMs) {
    const currentMs = Number.isFinite(Number(nowMs))
      ? Number(nowMs)
      : this.budget.startedAtMs;
    const ageMs = Math.max(0, currentMs - this.budget.startedAtMs);
    const lifetimeMs = this._getEffectiveLifetimeMs();
    const remainingMs = Math.max(0, lifetimeMs - ageMs);
    const empowered = this.empowered && ageMs < lifetimeMs;
    const nextShot = this.shotsFired + 1;
    const resonantEvery = Math.max(0, Math.floor(Number(this.definition.resonantEveryShots) || 0));
    const resonantReady = resonantEvery > 0 && nextShot % resonantEvery === 0;
    const finalWindow = empowered
      && Number(this.definition.finalWindowMs) > 0
      && remainingMs <= Number(this.definition.finalWindowMs);
    const projectileDamageMultiplier = roundHundredth(
      this.definition.projectileDamageMultiplier
        + this.storedBreakCharge
        + (resonantReady ? Number(this.definition.resonantDamageBonus) || 0 : 0),
    );
    const projectileSideLanes = this.definition.projectileSideLanes
      + (resonantReady ? Math.max(0, Number(this.definition.resonantSideLanes) || 0) : 0)
      + (finalWindow ? Math.max(0, Number(this.definition.finalWindowSideLanes) || 0) : 0);
    const states = this.definition.projectileStates || [];
    const maximumStateDamage = states.reduce(
      (maximum, state) => Math.max(maximum, Number(state.damageMultiplier) || 1),
      1,
    );
    const vfx = this.vfx?.getSnapshot?.() || {};
    return {
      active: empowered,
      empowered,
      projectileEnabled: empowered && this.definition.projectileEnabled === true,
      engineId: this.budget.engineId,
      activationId: this.budget.activationId,
      ageMs,
      lifetimeMs,
      remainingMs,
      impacts: this.projectileImpacts,
      maxImpacts: 0,
      bounces: 0,
      maxBounces: 0,
      redirects: 0,
      maxRedirects: 0,
      uniqueTargets: 0,
      projectileInfiniteRange: this.definition.projectileInfiniteRange === true,
      projectileRangeTiles: this.definition.projectileRangeTiles,
      projectileSafetyMaxTiles: this.definition.projectileSafetyMaxTiles,
      projectileDamageMultiplier,
      projectileMaximumDamageMultiplier: roundHundredth(
        projectileDamageMultiplier * maximumStateDamage,
      ),
      projectileStates: states,
      projectileStateCount: states.length,
      projectileSideLanes,
      projectilePassesGeodeWalls: this.definition.projectilePassesGeodeWalls,
      shotsFired: this.shotsFired,
      projectileImpacts: this.projectileImpacts,
      projectileDestroyed: this.projectileDestroyed,
      storedBreakCharge: roundHundredth(this.storedBreakCharge),
      lastConsumedBreakCharge: roundHundredth(this.lastConsumedBreakCharge),
      earnedLifetimeMs: this.earnedLifetimeMs,
      resonantReady,
      nextShot,
      finalWindow,
      playerVisualCount: this.playerVisualCount,
      liveVfxCount: vfx.liveVfxCount || 0,
      liveWakes: vfx.liveWakes || 0,
      wakeCount: vfx.wakeCount || 0,
      launchFlashCount: vfx.launchFlashCount || 0,
      stateBurstCount: vfx.stateBurstCount || 0,
      scheduledImpactCount: vfx.scheduledImpactCount || 0,
      impactMomentCount: vfx.impactMomentCount || 0,
      projectilePaletteCycle: vfx.paletteIds || [],
      lastProjectilePalette: this.lastProjectilePalette,
      paletteHistory: [...(this.paletteHistory || [])],
      liveProjectileCount: this.projectiles.size,
      projectileSpeedPxPerSecond: C.speedPxPerSecond,
      launchHistory: this.launchHistory.map(entry => ({ ...entry })),
    };
  }

  getSnapshot(nowMs) {
    return this.getBuffSnapshot(nowMs);
  }

  _getEffectiveLifetimeMs() {
    return Math.max(1, Number(this.definition.lifetimeMs) || 1)
      + Math.max(0, Number(this.earnedLifetimeMs) || 0);
  }

  _finish(nowMs) {
    if (!this.active || this.finishing) return;
    this.finishing = true;
    this.empowered = false;
    this._complete(nowMs);
  }

  _complete(nowMs) {
    if (!this.active) return;
    const health = this.getBuffSnapshot(nowMs);
    this.active = false;
    this._destroyVisual();
    this.onComplete?.("projectile-buff-ended", health);
  }

  _destroyVisual() {
    for (const projectile of this.projectiles || []) {
      this.scene.tweens?.killTweensOf?.(projectile);
      projectile.destroy?.();
    }
    this.projectiles?.clear?.();
    this.vfx?.destroy?.();
  }

  destroy() {
    this.active = false;
    this.empowered = false;
    this._destroyVisual();
  }
}

systems/celestial/StellarLanceVfx.js.before:
import { CELESTIAL_PRESENTATION as P } from "../../values/celestialPresentation.js";
import { CELESTIAL_ENGINE_CONFIG } from "../../values/celestialEngines.js";

const STELLAR_LANCE_PALETTES = P.lance.palettes;

/** Owns the authored launch, travel-state, and tile-contact VFX for Stellar Lance. */
export class StellarLanceVfx {
  constructor(options) {
    Object.assign(this, options);
    this.projectileAssetKeys = Array.isArray(options.projectileAssetKeys)
      ? options.projectileAssetKeys.filter(Boolean)
      : [];
    if (this.projectileAssetKeys.length === 0) {
      throw new Error("Stellar Lance requires the authored wave palette");
    }
    this.impactAssetKey = options.impactAssetKey
      || this.projectileAssetKeys[1]
      || this.projectileAssetKeys[0];
    this.effects = new Set();
    this.wakes = new Set();
    this.travelSamples = new WeakMap();
    this.strength = options.passive ? P.lance.passiveAlpha : 1;
    this.wakeCount = 0;
    this.launchFlashCount = 0;
    this.stateBurstCount = 0;
    this.scheduledImpactCount = 0;
    this.impactMomentCount = 0;
  }

  get paletteCount() {
    return Math.max(1, this.projectileAssetKeys.length);
  }

  getPalette(paletteIndex) {
    return STELLAR_LANCE_PALETTES[
      Math.max(0, Number(paletteIndex) || 0) % STELLAR_LANCE_PALETTES.length
    ];
  }

  getProjectileAssetKey(paletteIndex) {
    const index = Math.max(0, Number(paletteIndex) || 0)
      % this.projectileAssetKeys.length;
    return this.projectileAssetKeys[index];
  }

  applyState(sprite, stateIndex, sizeMultiplier = 1) {
    const states = this.definition.projectileStates || [];
    const state = states[Math.max(0, Math.min(states.length - 1, stateIndex))]
      || {};
    const stateScale = (Number(state.displayScale) || 1) * sizeMultiplier;
    sprite.setDisplaySize(
      this.definition.projectileDisplayWidthPx * stateScale,
      this.definition.projectileDisplayHeightPx * stateScale,
    );
    sprite.setAlpha(Math.min(
      CELESTIAL_ENGINE_CONFIG.fx.stellarRage.projectileAlpha,
      Number(state.alpha) || 1,
    ) * this.strength);
    return sprite;
  }

  transitionState(sprite, stateIndex) {
    const scaleX = sprite.scaleX;
    const scaleY = sprite.scaleY;
    const alpha = sprite.alpha;
    this.applyState(sprite, stateIndex);
    const targetX = sprite.scaleX;
    const targetY = sprite.scaleY;
    sprite.scaleX = scaleX;
    sprite.scaleY = scaleY;
    sprite.setAlpha(alpha);
    this.scene.tweens.add({ targets: sprite, scaleX: targetX, scaleY: targetY,
      duration: P.lance.stateBlendMs, ease: "Sine.inOut" });
  }

  trackTravel(sprite, nowMs) {
    const previous = this.travelSamples.get(sprite);
    if (!previous) {
      this.travelSamples.set(sprite, { x: sprite.x, y: sprite.y, at: nowMs });
      return;
    }
    const c = P.lance;
    if (nowMs - previous.at < c.wakeIntervalMs) return;
    const distance = Math.hypot(sprite.x - previous.x, sprite.y - previous.y);
    if (distance < c.wakeMinimumDistancePx) return;
    this.travelSamples.set(sprite, { x: sprite.x, y: sprite.y, at: nowMs });
    if (this.wakes.size >= c.wakeMaxLive) return;
    const palette = (sprite.celestialPaletteIndex + c.wakePaletteOffset) % this.paletteCount;
    const wake = this.scene.add.image(previous.x, previous.y, this.getProjectileAssetKey(palette))
      .setDisplaySize(sprite.displayWidth * c.wakeWidth, sprite.displayHeight * c.wakeHeight)
      .setAlpha(sprite.alpha * c.wakeAlpha * this.strength)
      .setBlendMode(Phaser.BlendModes.ADD)
      .setDepth(CELESTIAL_ENGINE_CONFIG.fx.worldDepth + P.coreDepthOffset);
    wake.angle = sprite.angle;
    this.effects.add(wake);
    this.wakes.add(wake);
    this.wakeCount += 1;
    this.scene.tweens.add({ targets: wake, alpha: 0,
      scaleX: wake.scaleX * c.wakeEndWidth, scaleY: wake.scaleY * c.wakeEndHeight,
      duration: c.wakeLifeMs, ease: "Sine.out", onComplete: () => this._release(wake) });
  }

  forgetTravel(sprite) {
    this.travelSamples.delete(sprite);
  }

  spawnLaunch(origin, angle, paletteIndex) {
    const cfg = CELESTIAL_ENGINE_CONFIG.fx.stellarRage;
    const image = this._createEffect(
      origin.x,
      origin.y,
      angle,
      0,
      cfg.launchFlashScale,
      cfg.launchFlashAlpha,
      paletteIndex,
    );
    this.launchFlashCount += 1;
    this._fadeEffect(image, cfg.launchFlashGrowth, cfg.launchFlashMs);
    return image;
  }

  spawnStateBurst(waypoint, angle, stateIndex, paletteIndex) {
    const cfg = CELESTIAL_ENGINE_CONFIG.fx.stellarRage;
    const image = this._createEffect(
      waypoint.tx * this.tileSize + this.tileSize / 2,
      waypoint.ty * this.tileSize + this.tileSize / 2,
      angle,
      stateIndex,
      cfg.stateBurstScale,
      cfg.stateBurstAlpha,
      paletteIndex,
    );
    this.stateBurstCount += 1;
    this._fadeEffect(image, cfg.stateBurstGrowth, cfg.stateBurstMs);
    return image;
  }

  spawnImpact(hit, paletteIndex, delayMs = 0, travelAngleDeg = 0) {
    const cfg = CELESTIAL_ENGINE_CONFIG.fx.stellarRage;
    const palette = this.getPalette(paletteIndex);
    const x = hit.tx * this.tileSize + this.tileSize / 2;
    const y = hit.ty * this.tileSize + this.tileSize / 2;
    const image = this.scene.add.image(x, y, this.impactAssetKey)
      .setBlendMode(Phaser.BlendModes.ADD)
      .setDepth(
        CELESTIAL_ENGINE_CONFIG.fx.worldDepth + cfg.transientDepthOffset + 1,
      )
      .setOrigin(cfg.projectileImpactOriginX, cfg.projectileImpactOriginY)
      .setDisplaySize(
        this.tileSize * cfg.projectileImpactDisplaySizeTiles,
        this.tileSize * cfg.projectileImpactDisplaySizeTiles,
      )
      .setAlpha(0);
    image.angle = (Number(travelAngleDeg) || 0)
      - cfg.projectileImpactAuthoredTravelAngleDeg;
    image.setTint?.(palette.impactTint);
    image.scaleX *= cfg.projectileImpactScale;
    image.scaleY *= cfg.projectileImpactScale;
    this.effects.add(image);
    this.scheduledImpactCount += 1;

    this.scene.tweens.add({
      targets: image,
      alpha: 0,
      delay: Math.max(0, Math.round(delayMs)),
      duration: 1,
      onComplete: () => {
        if (!this.effects.has(image)) return;
        image.setAlpha(0);
        this.impactMomentCount += 1;
        const baseX = image.scaleX;
        const baseY = image.scaleY;
        this.scene.tweens.add({
          targets: image,
          alpha: cfg.projectileImpactAlpha * this.strength,
          scaleX: baseX * P.lance.impactAttackScale,
          scaleY: baseY * P.lance.impactAttackScale,
          duration: P.lance.impactAttackMs,
          ease: "Sine.out",
          onComplete: () => {
            if (!this.effects.has(image)) return;
            this.scene.tweens.add({
              targets: image,
              scaleX: baseX * cfg.projectileImpactGrowth,
              scaleY: baseY * cfg.projectileImpactGrowth,
              alpha: 0,
              angle: image.angle + cfg.projectileImpactRotationDeg,
              duration: cfg.projectileImpactMs,
              ease: "Sine.out",
              onComplete: () => this._release(image),
            });
          },
        });
      },
    });
    return image;
  }

  _createEffect(x, y, angle, stateIndex, scale, alpha, paletteIndex) {
    const cfg = CELESTIAL_ENGINE_CONFIG.fx.stellarRage;
    const image = this.scene.add.image(
      x,
      y,
      this.getProjectileAssetKey(paletteIndex),
    ).setBlendMode(Phaser.BlendModes.ADD)
      .setDepth(CELESTIAL_ENGINE_CONFIG.fx.worldDepth + cfg.transientDepthOffset);
    image.angle = angle;
    this.applyState(image, stateIndex, scale).setAlpha(alpha * this.strength);
    this.effects.add(image);
    return image;
  }

  _fadeEffect(image, growth, duration) {
    this.scene.tweens.add({
      targets: image,
      scaleX: image.scaleX * growth,
      scaleY: image.scaleY * growth,
      alpha: 0,
      duration,
      ease: "Power2.out",
      onComplete: () => this._release(image),
    });
  }

  _release(image) {
    this.effects.delete(image);
    this.wakes.delete(image);
    image?.destroy?.();
  }

  getSnapshot() {
    return Object.freeze({
      liveVfxCount: this.effects.size,
      liveWakes: this.wakes.size,
      wakeCount: this.wakeCount,
      launchFlashCount: this.launchFlashCount,
      stateBurstCount: this.stateBurstCount,
      scheduledImpactCount: this.scheduledImpactCount,
      impactMomentCount: this.impactMomentCount,
      paletteIds: STELLAR_LANCE_PALETTES.map(palette => palette.id),
    });
  }

  destroy() {
    for (const effect of this.effects) {
      this.scene.tweens?.killTweensOf?.(effect);
      effect.destroy?.();
    }
    this.effects.clear();
    this.wakes.clear();
    this.travelSamples = new WeakMap();
  }
}

